-- -*- mode: lua -*-

-- MIDI map for the Novation Launchkey Mini MK3 keyboard.
-- Albert Gräf <agggraef@gmail.com>, 13 April 2024

-- This contains the default MIDI map for the Launchkey driver, as well as
-- some rudimentary bindings for the buttons and knobs in standalone mode
-- (these are only active if the Launchkey driver is turned off). To use this,
-- load the map in Raptor and connect the Launchkey Mini to Pd's first MIDI
-- input. In addition, to use the built-in driver, also connect the second
-- (DAW) port to Pd's second port, for both input and output. The map assumes
-- the factory setup for the knobs (CC21-28).

-- This might also work for the bigger Launchkey MK3 devices, but I haven't
-- tested those yet.

-- STANDALONE:

-- The standalone map binds all buttons that can be accessed without session/
-- DAW mode on a Mini MK3. Note that the bigger Launchkey MK3 models have a
-- lot more mappable buttons, you're free to map those in addition to the
-- buttons listed below. The standalone map, as well as the driver's session
-- mode map described below, were chosen so that they will work on *any*
-- Launchkey MK3 device, and the Mini MK3 is the most limited of these.

-- Bindings with Raptor functions given in parentheses:
-- - The (unshifted) ">" and "Stop/Solo/Mute" buttons (latch, mute), these also
--   work in session mode.
-- - The transport buttons (play, loop).
-- - The (shifted) track left/right buttons (rewind, pulse).

-- The knobs are mapped as in the first fader bank of the Launchpad, i.e.,
-- from left to right: 1 = pitch hi, 2 = pitch lo, 3 = pattern mode (random,
-- up, down, etc.), 4 = pos/anacrusis (the "scrubbing" control), 5 = tempo,
-- 6 = meter numerator, 7 = meter denominator, 8 = division. These bindings
-- will also work in session mode if you choose the Custom knob mode.

-- SESSION/DAW MODE:

-- The session a.k.a. DAW mode binding works pretty much like the Launchpad
-- one (within the limitations of the device), with the knobs mapped to the
-- same four banks of Raptor controls under the corresponding knob modes
-- (Volume, Pan, Send A+B), and the 2x8 grid functioning either as launch or
-- drum pads, depending on the pad mode (Session or Drums). Just like on the
-- Launchpad, the pads are fully mappable in Session pad mode, and the default
-- binding matches the two bottom rows of the Launchpad's grid.

-- The arrow keys let you select Raptor instances (left, right) and presets
-- (up, down). Note that on the Mini MK3 you'll have to press Shift to get
-- these. The transport buttons work as well (play, loop), and also light up
-- to reflect the current transport/loop playback state. The Stop button will
-- work in DAW mode as well (it stops the transport if it is currently
-- rolling). This button is only available on the bigger Launchkey devices,
-- but on the Mini you can press Shift+Play instead to get this function.

-- NOTE: In session mode, you'll have two more knob modes available: Custom
-- knob mode which for consistency works like in standalone mode (so it
-- replicates what you already have on the Volume bank), and Device knob mode
-- which is not used by the driver and is separate from Custom mode, so those
-- knobs can be mapped to whatever you want.

-- To come up with reasonable default bindings for the Device knobs, I mapped
-- them to the Raptor controls that I use most frequently (see the controls in
-- boldface in doc/raptor7-cheatsheet.pdf), so that I have all of these on tap
-- without having to switch back and forth between the four preconfigured
-- banks so often. YMMV, of course, so feel free to reassign these to whatever
-- controls *you* use most frequently.

{
  -- standalone knob bindings, these work the same in session mode if you
  -- choose the Custom knob mode
  [21]  = { [1] = "pitchhi" },
  [22]  = { [1] = "pitchlo" },
  [23]  = { [1] = "mode" },
  [24]  = { [1] = "pos" },
  [25]  = { [1] = "tempo" },
  [26]  = { [1] = "meter-num" },
  [27]  = { [1] = "meter-denom" },
  [28]  = { [1] = "division" },
  -- standalone button assignments (pulse/rewind only work in standalone mode,
  -- the others also in session mode which also has alternative launch grid
  -- bindings for all these functions)
  [102] = { [16] = { "pulse", true } },
  [103] = { [16] = { "rewind", true } },
  [104] = { [16] = { "latch", true } },
  [105] = { [16] = { "mute", true } },
  [115] = { [16] = { "play", true } },
  [117] = { [16] = { "loop", true } },
  -- session mode bindings (only active if the launchkey driver is turned on)
  -- send A (min value) faders
  [13] = { [32] = "minvel" },
  [14] = { [32] = "pmin" },
  [15] = { [32] = "wmin" },
  [16] = { [32] = "gate" },
  [17] = { [32] = "hmin" },
  [18] = { [32] = "pref" },
  [19] = { [32] = "smin" },
  [20] = { [32] = "uniq" },
  -- send B (max value) faders
  [29] = { [32] = "maxvel" },
  [30] = { [32] = "pmax" },
  [31] = { [32] = "wmax" },
  [32] = { [32] = "gate" },
  [33] = { [32] = "hmax" },
  [34] = { [32] = "pref" },
  [35] = { [32] = "smax" },
  [36] = { [32] = "nmax" },
  -- pan (bipolar mod) faders
  [49] = { [32] = "velmod" },
  [50] = { [32] = "pmod" },
  [51] = { [32] = "gain" },
  [52] = { [32] = "gatemod" },
  [53] = { [32] = "hmod" },
  [54] = { [32] = "prefmod" },
  [55] = { [32] = "smod" },
  [56] = { [32] = "nmod" },
  -- volume faders
  [77] = { [32] = "pitchhi" },
  [78] = { [32] = "pitchlo" },
  [79] = { [32] = "mode" },
  [80] = { [32] = "pos" },
  [81] = { [32] = "tempo" },
  [82] = { [32] = "meter-num" },
  [83] = { [32] = "meter-denom" },
  [84] = { [32] = "division" },
  -- device mode faders (selection of most frequently used controls)
  [21]  = { [32] = "mode" },
  [22]  = { [32] = "pos" },
  [23]  = { [32] = "gain" },
  [24]  = { [32] = "gate" },
  [25]  = { [32] = "hmin" },
  [26]  = { [32] = "hmax" },
  [27]  = { [32] = "pref" },
  [28]  = { [32] = "prefmod" },
  -- alternative bindings for latch/mute, same as in standalone
  -- NOTE: standalone bindings repeated here, so that they aren't overridden
  [104] = { [17] = { "latch", true }, [16] = { "latch", true } },
  [105] = { [17] = { "mute", true }, [16] = { "mute", true } },
  -- transport
  -- NOTE: standalone bindings repeated here, so that they aren't overridden
  [115] = { [32] = { "play", true }, [16] = { "play", true } },
  [117] = { [32] = { "loop", true }, [16] = { "loop", true } },
  -- predefined pads (session view)
  -- 240, 241 unassigned
  [242] = { [17] = { "raptor", true } },
  [243] = { [17] = { "rewind", true } },
  -- 244 unassigned
  [245] = { [17] = { "loop-prev", true } },
  [246] = { [17] = { "loop-next", true } },
  [247] = { [17] = { "play", true } },
  -- upper row
  [224] = { [17] = { "mute", true } },
  [225] = { [17] = { "latch", true } },
  [226] = { [17] = { "bypass", true } },
  -- 227, 228 unassigned
  [229] = { [17] = { "loop-load", true } },
  [230] = { [17] = { "loop-save", true } },
  [231] = { [17] = { "loop", true } },
}
